def slug(s):
 s=s.lower().replace('đ','dj')
 return re.sub('[^a-z0-9]+','-',unicodedata.normalize('NFKD',s).encode('ascii','ignore').decode()).strip('-')
categories=[{'id':'cat-'+str(i+1),'slug':slug(s),'name':dict(zip(['sr','en','ru','tr','zh'],[s,cat_en[i],cat_ru[i],cat_tr[i],cat_zh[i]])),'icon':str(i),'published':True} for i,s in enumerate(cat_sr)]
tools=[]
for i,x in enumerate(src):
 names=dict(zip(['sr','en','ru','tr','zh'],[x['name'],en[i],ru[i],tr[i],zh[i]]))
 desc={'sr':f"{x['name']} za iznajmljivanje u Beogradu i okolini. Pošalji nam opis posla i željene datume kako bismo potvrdili odgovarajući model, dodatke i uslove najma.",'en':f"{en[i]} for rent in Belgrade and surrounding areas. Tell us about your project and dates so we can confirm the right model, accessories and rental terms.",'ru':f"{ru[i]} в аренду в Белграде и окрестностях. Опишите задачу и даты, чтобы мы подтвердили подходящую модель, принадлежности и условия.",'tr':f"Belgrad ve çevresinde kiralık: {tr[i]}. Uygun modeli, aksesuarları ve kiralama koşullarını onaylamak için projenizi ve tarihleri belirtin.",'zh':f"{zh[i]}可在贝尔格莱德及周边租赁。请告知项目内容和日期，以便确认合适的型号、配件及租赁条件。"}
 tools.append({'id':x['id'],'slug':slug(x['name']),'name':names,'description':desc,'categoryId':categories[cat_sr.index(x['category'])]['id'],'price':None,'deposit':None,'quantity':None,'image':'','published':True,'featured':i in [0,2,22,23,25,54,66,15],'updatedAt':'2026-10-10T00:00:00.000Z'})
enrichment=json.loads(Path('lib/catalog-enrichment.json').read_text())
for tool in tools:
 tool.update(enrichment.get(tool['id'],{}))
 tool['deposit']=0
# Include the deduplicated additions when rebuilding the original reference seed.
known={tool['slug'] for tool in tools}
for filename in ['lib/catalog-import.json', 'lib/catalog-expansion.json']:
 imported=json.loads(Path(filename).read_text())
 for tool in imported['tools']:
  if tool['slug'] not in known: tools.append(tool); known.add(tool['slug'])
Path('lib/seed.json').write_text(json.dumps({'tools':tools,'categories':categories},ensure_ascii=False,indent=2))
